from collections import OrderedDict


class Policy:
    def __init__(self, capacity_bytes: int):
        self.capacity_bytes = max(0, capacity_bytes)
        self._items = {}
        self._recent = OrderedDict()
        self._frequent = OrderedDict()
        self._used = 0
        self._frequent_bytes = 0

    def _frequent_limit(self):
        if self.capacity_bytes <= 1:
            return self.capacity_bytes
        return max(1, (self.capacity_bytes * 2) // 3)

    def _rebalance(self):
        limit = self._frequent_limit()
        while self._frequent and self._frequent_bytes > limit:
            key, _ = self._frequent.popitem(last=False)
            entry = self._items.get(key)
            if entry is None or entry[2] != 1:
                continue
            entry[2] = 0
            self._frequent_bytes -= entry[0]
            self._recent[key] = None

    def _remove(self, key):
        entry = self._items.pop(key)
        size, _, frequent = entry
        self._recent.pop(key, None)
        self._frequent.pop(key, None)
        self._used -= size
        if frequent:
            self._frequent_bytes -= size

    def _touch(self, key):
        entry = self._items[key]
        entry[1] = min(entry[1] + 1, 15)
        if entry[2]:
            self._frequent.move_to_end(key)
        elif entry[1] >= 2:
            self._recent.pop(key, None)
            entry[2] = 1
            self._frequent[key] = None
            self._frequent_bytes += entry[0]
        else:
            self._recent.move_to_end(key)
        self._rebalance()

    def access(self, key: int, size: int, now: int) -> list[int]:
        if key in self._items:
            self._touch(key)
            return []

        size = max(0, size)
        if self.capacity_bytes == 0 or size > self.capacity_bytes:
            return []

        evicted = []
        while self._used + size > self.capacity_bytes:
            if self._recent:
                victim, _ = self._recent.popitem(last=False)
            elif self._frequent:
                victim, _ = self._frequent.popitem(last=False)
            else:
                break
            self._remove(victim)
            evicted.append(victim)

        self._items[key] = [size, 1, 0]
        self._recent[key] = None
        self._used += size
        self._rebalance()
        return evicted
